<script setup lang="ts">
import { Search, Plus, Sparkles, ArrowUpRight, Copy, BookOpen, SlidersHorizontal, Pencil, Trash2, FolderInput, ChevronDown, LayoutTemplate, Layers3 } from 'lucide-vue-next'
import { categories, normalizePalette, defaultPalette, type Palette, type Resource } from '@qinbian/shared'
const ctx=useQinbian(),items=ref<Resource[]>([]),kind=ref<'component'|'template'|'palette'>('component'),allPalettes=ref<Resource[]>([]),applyCard=ref<Resource|null>(null),applyTheme=ref('mine'),query=ref(''),category=ref(''),loading=ref(true),preview=ref<Resource|null>(null),width=ref(375),aiOpen=ref(false),newOpen=ref(false),newName=ref(''),moving=ref<Resource|null>(null),moveTheme=ref('mine'),editingTheme=ref(false),themeDraft=ref({name:'',description:'',rules:'',tokens:{} as Record<string,string>,palette:normalizePalette()})
const theme=computed(()=>ctx.themes.value.find(t=>t.id===ctx.activeTheme.value))
const filtered=computed(()=>(kind.value==='palette'?allPalettes.value:items.value.filter(r=>r.kind===kind.value)).filter(r=>kind.value==='palette'||!category.value||r.category===category.value).filter(r=>!query.value||[r.name,r.description,...r.tags,r.legacyId||''].join(' ').toLowerCase().includes(query.value.toLowerCase())))
const visibleLimit=ref(12)
watch([query,category,kind,()=>ctx.activeTheme.value],()=>visibleLimit.value=12)
const visibleItems=computed(()=>filtered.value.slice(0,visibleLimit.value))
const count=(k:string)=>k==='palette'?allPalettes.value.length:items.value.filter(r=>r.kind===k).length
const kindName=computed(()=>kind.value==='component'?'组件':kind.value==='template'?'编排模板':'配色卡')
async function refresh(){loading.value=true;try{const result=await Promise.all([apiFetch<Resource[]>('/api/resources',{query:ctx.activeTheme.value?{themeSetId:ctx.activeTheme.value}:{}}),apiFetch<Resource[]>('/api/resources',{query:{kind:'palette'}})]);items.value=result[0];allPalettes.value=result[1]}catch(e){ctx.error(e)}finally{loading.value=false}}
watch(()=>ctx.activeTheme.value,()=>{category.value='';void refresh()});onMounted(refresh)
function html(r:Resource){return r.kind==='component'?r.data.html||'':(r.data.blocks||[]).map(b=>b.html).join('')}
async function edit(r:Resource){try{if(r.builtin){const c=await apiFetch<Resource>(`/api/resources/${r.id}/clone`,{method:'POST',body:{themeSetId:'mine'}});navigateTo('/resources/'+c.id)}else navigateTo('/resources/'+r.id)}catch(e){ctx.error(e)}}
async function clone(r:Resource){try{await apiFetch(`/api/resources/${r.id}/clone`,{method:'POST',body:{themeSetId:theme.value&&!theme.value.builtin?theme.value.id:'mine'}});ctx.notify('副本已收进资源库');await refresh()}catch(e){ctx.error(e)}}
async function use(r:Resource){if(r.kind==='palette'){applyCard.value=r;return}try{const d=await apiFetch<any>('/api/documents',{method:'POST',body:{resourceId:r.id}});navigateTo('/documents/'+d.id)}catch(e){ctx.error(e)}}
async function remove(r:Resource){if(!confirm(`将“${r.name}”移到回收站？`))return;try{await apiFetch(`/api/resources/${r.id}`,{method:'DELETE'});await refresh();ctx.notify('资源已移到回收站')}catch(e){ctx.error(e)}}
async function move(){if(!moving.value)return;try{await apiFetch(`/api/resources/${moving.value.id}`,{method:'PUT',body:{...moving.value,themeSetId:moveTheme.value}});moving.value=null;await refresh();ctx.notify('资源已移入所选套组')}catch(e){ctx.error(e)}}
async function create(){if(!newName.value.trim())return;try{const r=await apiFetch<Resource>('/api/resources',{method:'POST',body:{kind:kind.value,name:newName.value,themeSetId:theme.value&&!theme.value.builtin?theme.value.id:'mine',data:kind.value==='component'?{html:'<section style="padding:24px;background-color:#FFFCF6;border-left:2px solid #567067;"><p style="font-size:20px;line-height:1.5;color:#183A49;"><span leaf="">在这里写下标题</span></p><p style="font-size:15px;line-height:1.85;color:#293F4F;"><span leaf="">从一段文字开始，慢慢写成自己的章法。</span></p></section>'}:kind.value==='palette'?{palette:normalizePalette(theme.value?.palette,theme.value?.tokens)}:{blocks:[]}}});newOpen.value=false;newName.value='';navigateTo('/resources/'+r.id)}catch(e){ctx.error(e)}}
function beginThemeEdit(){if(!theme.value)return;themeDraft.value={name:theme.value.name,description:theme.value.description,rules:theme.value.rules,tokens:{...theme.value.tokens},palette:normalizePalette(theme.value.palette,theme.value.tokens)};editingTheme.value=true}
async function saveTheme(){if(!theme.value)return;try{await apiFetch('/api/theme-sets/'+theme.value.id,{method:'PATCH',body:themeDraft.value});await ctx.refreshThemes();editingTheme.value=false;ctx.notify('套组信息已保存')}catch(e){ctx.error(e)}}
async function deleteTheme(){if(!theme.value||!confirm('删除此套组？其中的资源和文章会移入“我的资源”。'))return;try{await apiFetch('/api/theme-sets/'+theme.value.id,{method:'DELETE'});ctx.activeTheme.value='mine';await ctx.refreshThemes();editingTheme.value=false}catch(e){ctx.error(e)}}
async function applyPaletteCard(){if(!applyCard.value)return;try{await apiFetch('/api/resources/'+applyCard.value.id+'/apply-palette',{method:'POST',body:{themeSetId:applyTheme.value}});await ctx.refreshThemes();applyCard.value=null;ctx.notify('配色卡已用于所选套组')}catch(e){ctx.error(e)}}
</script>
<template><div class="page library-page"><header class="page-heading"><div><p class="eyebrow">版式有序 · 灵感有处</p><h1>{{kind==='palette'?'配色卡':theme?.name||'全部资源'}}<span class="title-dot">。</span></h1><p class="page-description">{{kind==='palette'?'留住一组好颜色，让不同的版式彼此呼应。':theme?.description||'将常用的组件与编排模板，收进自己的书房。'}}</p></div><div class="heading-actions"><button v-if="theme&&!theme.builtin" class="icon-button" aria-label="编辑主题套组" @click="beginThemeEdit"><SlidersHorizontal :size="18"/></button><button class="btn ai-button" @click="aiOpen=true"><Sparkles :size="16"/>AI 制作</button><button class="btn primary" @click="newOpen=true"><Plus :size="17"/>新建{{kindName}}</button></div></header>
 <div class="collection-meta"><span v-if="theme?.builtin" class="subtle-badge">内置套组 · 修改时另存副本</span><span v-else class="subtle-badge">我的收藏与创作</span><span class="palette-dots"><i v-for="(value,name) in theme?.tokens" :key="name" :title="String(name)" :style="{background:value}"/></span><span class="collection-count">{{count('component')}} 枚组件<span>／</span>{{count('template')}} 套模板<span>／</span>{{count('palette')}} 张配色卡</span></div>
 <div class="library-controls"><div class="tab-line"><button :class="{active:kind==='component'}" @click="kind='component';category=''"><Layers3 :size="16"/>组件 <small>{{count('component')}}</small></button><button :class="{active:kind==='template'}" @click="kind='template';category=''"><LayoutTemplate :size="16"/>编排模板 <small>{{count('template')}}</small></button><button :class="{active:kind==='palette'}" @click="kind='palette';category=''"><SlidersHorizontal :size="16"/>配色卡 <small>{{count('palette')}}</small></button></div><label class="search-field"><Search :size="16"/><input v-model="query" placeholder="寻一枚组件，或一个关键词…" aria-label="搜索资源"><kbd>⌕</kbd></label></div>
 <div v-if="kind==='component'" class="category-line"><button :class="{active:!category}" @click="category=''">全部</button><button v-for="c in categories" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div>
 <div v-if="loading" class="empty-state muted">正在展开这份收藏…</div><div v-else-if="!filtered.length" class="empty-state"><BookOpen :size="36"/><h3>{{query?'换一个词，再找找':'这一页，留给新的灵感'}}</h3><p>可以创建组件，用 AI 制作，或从内置套组另存一份。</p></div>
 <div v-else class="resource-grid"><article v-for="(r,i) in visibleItems" :key="r.id" class="resource-card"><button class="card-preview-button" :aria-label="'预览 '+r.name" @click="preview=r"><div class="resource-card-meta"><span>{{r.legacyId||String(i+1).padStart(2,'0')}}</span><span>{{r.kind==='template'?'编排模板':r.category}}</span></div><PaletteSwatches v-if="r.kind==='palette'" :palette="r.data.palette" compact/><HtmlPreview v-else :html="html(r)" compact :max-height="230"/><div class="preview-curtain"><span>展开预览 <ArrowUpRight :size="14"/></span></div></button><div class="resource-card-info"><div class="card-name"><h2>{{r.name}}</h2><span v-if="r.kind==='template'" class="small muted">{{r.data.blocks?.length}} 枚组件</span></div><p>{{r.description}}</p><div class="tags"><span v-for="tag in r.tags.slice(0,3)" :key="tag">{{tag}}</span></div><div class="resource-card-actions"><button class="text-button" @click="edit(r)"><Pencil :size="13"/>{{r.builtin?'编辑副本':'编辑'}}</button><button class="icon-button" :aria-label="'复制 '+r.name" title="另存一份" @click="clone(r)"><Copy :size="14"/></button><button v-if="!r.builtin" class="icon-button" :aria-label="'移动 '+r.name" title="移动到套组" @click="moving=r;moveTheme=r.themeSetId"><FolderInput :size="14"/></button><button v-if="!r.builtin" class="icon-button" :aria-label="'删除 '+r.name" @click="remove(r)"><Trash2 :size="14"/></button><button class="card-use-button" @click="use(r)">{{r.kind==='palette'?'用于套组':r.kind==='template'?'用此模板':'编成文章'}}<ArrowUpRight :size="14"/></button></div></div></article></div>
 <div v-if="filtered.length>visibleLimit" class="load-more"><button class="btn" @click="visibleLimit+=12">再展开 {{Math.min(12,filtered.length-visibleLimit)}} 份版式 <ChevronDown :size="14"/></button><span class="small muted">已展示 {{visibleLimit}} / {{filtered.length}}</span></div>
 <footer class="page-footer"><span>把结构交给组件，把表达留给自己。</span><small>秦编 · 私人编排书房</small></footer>
 <UiModal v-if="preview" :title="preview.name" :subtitle="preview.description" wide @close="preview=null"><div class="preview-width-tabs"><button v-for="w in [320,375,414]" :key="w" :class="{active:width===w}" @click="width=w">{{w}}</button><span>正文宽度</span></div><div class="preview-paper" :style="{maxWidth:width+'px'}"><PaletteSwatches v-if="preview.kind==='palette'" :palette="preview.data.palette"/><HtmlPreview v-else :html="html(preview)" :width="width"/></div><div class="modal-actions"><button class="btn" @click="edit(preview)">编辑副本</button><button class="btn primary" @click="use(preview)">{{preview.kind==='palette'?'用于主题套组':'用它开始一篇文章'}}</button></div></UiModal>
 <UiModal v-if="aiOpen" :title="kind==='palette'?'AI 生成配色卡':'AI 制作组件'" subtitle="用一句具体的描述，开启一枚新组件。" @close="aiOpen=false"><AiPanel :mode="kind==='palette'?'palette':'component'" :theme-set-id="ctx.activeTheme.value||'shanhai'" @applied="refresh"/></UiModal>
 <UiModal v-if="newOpen" :title="'新建'+kindName" @close="newOpen=false"><form class="form-stack" @submit.prevent="create"><label>名称<input v-model="newName" required placeholder="给它一个便于寻找的名字" autofocus></label><p class="small muted">{{theme?.builtin?'内置原件会保留，新创作将收进“我的资源”。':'将保存在当前套组中。'}}</p><div class="modal-actions"><button type="button" class="btn" @click="newOpen=false">取消</button><button class="btn primary">创建并编辑</button></div></form></UiModal>
 <UiModal v-if="moving" title="移动到套组" @close="moving=null"><div class="form-stack"><label>选择套组<select v-model="moveTheme"><option v-for="t in ctx.themes.value.filter(t=>!t.builtin)" :key="t.id" :value="t.id">{{t.name}}</option></select></label><div class="modal-actions"><button class="btn primary" @click="move">确认移动</button></div></div></UiModal>
 <UiModal v-if="editingTheme" title="编辑主题套组" @close="editingTheme=false"><form class="form-stack" @submit.prevent="saveTheme"><label>名称<input v-model="themeDraft.name" required></label><label>说明<textarea v-model="themeDraft.description" rows="2"/></label><PaletteEditor v-model="themeDraft.palette"/><label>制作要求<textarea v-model="themeDraft.rules" rows="4" placeholder="这些规则会随套组用于AI制作。"/></label><div class="modal-actions"><button v-if="theme?.id!=='mine'" class="text-button danger" type="button" @click="deleteTheme">删除套组</button><button class="btn primary">保存套组</button></div></form></UiModal>
<UiModal v-if="applyCard" title="将配色用于套组" @close="applyCard=null"><div class="form-stack"><PaletteSwatches :palette="applyCard.data.palette" compact/><label>选择套组<select v-model="applyTheme"><option v-for="t in ctx.themes.value.filter(t=>!t.builtin)" :key="t.id" :value="t.id">{{t.name}}</option></select></label><p class="small muted">之后的AI制作会使用这份配色；已有文章保留自己的快照。</p><div class="modal-actions"><button class="btn primary" @click="applyPaletteCard">应用配色</button></div></div></UiModal></div></template>
